python3 -c $'import sys,json,collections,math,itertools\nfrom fractions import Fraction as F\nC="Cosmic Love Is The Solution(s) For Everything."\nG=lambda b:__import__("functools").reduce(lambda n,v:n*257+v+1,b,1)\ndef D(n):\n b=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError("code")\n  b.insert(0,r-1)\n return bytes(b)\ndef E(a):\n c=collections.Counter(a);n=len(a)\n return "0" if len(c)<2 else "- ("+" + ".join(str(F(v,n))+"*log2("+str(F(v,n))+")" for v in c.values())+")"\ndef primes(n):\n a=[];x=2\n while len(a)<n:\n  if all(x%p for p in a if p*p<=x):a.append(x)\n  x+=1\n return a\nsrc=repr((G.__code__.co_code,D.__code__.co_code,E.__code__.co_code))+C\nw=src;v=sorted(set(w));ps=primes(len(v));a=dict(zip(v,ps));t=[a[c] for c in w];hi=E(t);g=G(w.encode());assert D(g).decode()==w\nfor i in range(len(t)):t[i]=C\nhf=E(t);assert hf=="0"\nprint(json.dumps({"system":"M45-PRIME-GODEL","atoms":len(v),"max_prime":ps[-1],"godel":str(g),"H_init_exact":hi,"H_final_exact":hf,"invariant":C,"status":"HALT"},ensure_ascii=False,separators=(",",":")))'
